package cmd

import (
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"os"
	"strings"

	"task-cli/internal/db"
)

// ExportArgs represents the argument schema for the export command.
type ExportArgs struct {
	OutFlag        string
	Pretty         bool
	ProjectFilter  string
	StatusFilter   string
	IncludeDeleted bool
	DryRun         bool
	Quiet          bool
}

// ExportResult holds data and statistics generated by the export operation.
type ExportResult struct {
	Data        *db.TransferData
	RawJSON     []byte
	OutFlag     string
	DryRun      bool
	Quiet       bool
	NumProjects int
	NumTasks    int
	NumDocs     int
}

// ExportAction encapsulates schema parsing, execution, and output formatting for JSON exports.
type ExportAction struct{}

// Parse parses and validates arguments and flags for export.
func (a *ExportAction) Parse(ctx *Context, args []string) (ExportArgs, error) {
	exportCmd := flag.NewFlagSet("export", flag.ContinueOnError)
	var outFlag string
	var prettyFlag bool
	var projectFlag string
	var statusFlag string
	var includeDeletedFlag bool
	var dryRunFlag bool
	var quietFlag bool

	exportCmd.StringVar(&outFlag, "out", "", "Output file path (default: stdout)")
	exportCmd.StringVar(&outFlag, "o", "", "Output file path (shorthand)")
	exportCmd.BoolVar(&prettyFlag, "pretty", false, "Pretty print JSON output")
	exportCmd.StringVar(&projectFlag, "f", "", "Filter tasks by project code (shorthand)")
	exportCmd.StringVar(&projectFlag, "filter", "", "Filter tasks by project code")
	exportCmd.StringVar(&projectFlag, "proj", "", "Filter tasks by project code")
	exportCmd.StringVar(&projectFlag, "project", "", "Filter tasks by project code")
	exportCmd.StringVar(&statusFlag, "status", "", "Filter tasks by status")
	exportCmd.StringVar(&statusFlag, "s", "", "Filter tasks by status (shorthand)")
	exportCmd.BoolVar(&includeDeletedFlag, "include-deleted", false, "Include soft-deleted tasks in export")
	exportCmd.BoolVar(&dryRunFlag, "dry-run", false, "Simulate export without writing output")
	exportCmd.BoolVar(&quietFlag, "q", false, "Suppress non-essential messages (shorthand)")
	exportCmd.BoolVar(&quietFlag, "quiet", false, "Suppress non-essential messages")

	flagArgs, _ := splitFlagsAndPosArgs(args, map[string]bool{
		"-o":        true,
		"--out":     true,
		"-f":        true,
		"--filter":  true,
		"-proj":     true,
		"--project": true,
		"-s":        true,
		"--status":  true,
	})

	if err := exportCmd.Parse(flagArgs); err != nil {
		return ExportArgs{}, err
	}

	return ExportArgs{
		OutFlag:        outFlag,
		Pretty:         prettyFlag,
		ProjectFilter:  projectFlag,
		StatusFilter:   statusFlag,
		IncludeDeleted: includeDeletedFlag,
		DryRun:         dryRunFlag,
		Quiet:          quietFlag,
	}, nil
}

// Execute queries the database and generates the exported data structure.
func (a *ExportAction) Execute(ctx *Context, args ExportArgs) (*ExportResult, error) {
	data, err := ctx.Store.ExportData(ctx.Context(), db.ExportOptions{
		ProjectCode:    args.ProjectFilter,
		Status:         args.StatusFilter,
		IncludeDeleted: args.IncludeDeleted,
	})
	if err != nil {
		return nil, err
	}

	numProjects := len(data.Projects)
	numTasks := len(data.StandaloneTasks)
	numDocs := 0
	for _, t := range data.StandaloneTasks {
		numDocs += len(t.Documents)
	}
	for _, p := range data.Projects {
		numTasks += len(p.Tasks)
		for _, t := range p.Tasks {
			numDocs += len(t.Documents)
		}
	}

	var raw []byte
	if !args.DryRun {
		if args.Pretty {
			raw, err = json.MarshalIndent(data, "", "  ")
		} else {
			raw, err = json.Marshal(data)
		}
		if err != nil {
			return nil, fmt.Errorf("failed to encode JSON: %w", err)
		}

		if args.OutFlag != "" {
			if err := os.WriteFile(args.OutFlag, append(raw, '\n'), 0644); err != nil {
				return nil, fmt.Errorf("failed to write export file: %w", err)
			}
		}
	}

	return &ExportResult{
		Data:        data,
		RawJSON:     raw,
		OutFlag:     args.OutFlag,
		DryRun:      args.DryRun,
		Quiet:       args.Quiet,
		NumProjects: numProjects,
		NumTasks:    numTasks,
		NumDocs:     numDocs,
	}, nil
}

// Format renders the export results to the output writer.
func (a *ExportAction) Format(ctx *Context, w io.Writer, res *ExportResult) error {
	if res.DryRun {
		fmt.Fprintf(w, "[dry-run] Export: %d project(s), %d task(s), %d document(s)\n", res.NumProjects, res.NumTasks, res.NumDocs)
		return nil
	}

	if res.OutFlag != "" {
		if !res.Quiet {
			fmt.Fprintf(w, "Data exported successfully to %s (%d projects, %d tasks, %d documents)\n", res.OutFlag, res.NumProjects, res.NumTasks, res.NumDocs)
		}
	} else {
		fmt.Fprintln(w, string(res.RawJSON))
	}

	return nil
}

// ExportHandler is the standardized handler instance for ExportAction.
var ExportHandler = NewActionHandler(&ExportAction{})

// Export serializes projects, tasks, and documents to JSON.
func Export(ctx *Context, args []string) error {
	return ExportHandler.Run(ctx, args)
}

// ImportArgs represents the argument schema for the import command.
type ImportArgs struct {
	RawData   []byte
	Overwrite bool
	Strict    bool
	ForceDocs bool
	DryRun    bool
	Quiet     bool
}

// ImportResultWrapper holds the import outcome and options.
type ImportResultWrapper struct {
	Result *db.ImportResult
	DryRun bool
	Quiet  bool
}

// ImportAction encapsulates schema parsing, execution, and output formatting for JSON imports.
type ImportAction struct{}

// Parse parses arguments, flags, and reads input from file or stdin.
func (a *ImportAction) Parse(ctx *Context, args []string) (ImportArgs, error) {
	importCmd := flag.NewFlagSet("import", flag.ContinueOnError)
	var dryRunFlag bool
	var overwriteFlag bool
	var strictFlag bool
	var forceDocsFlag bool
	var quietFlag bool

	importCmd.BoolVar(&dryRunFlag, "dry-run", false, "Simulate import without committing changes")
	importCmd.BoolVar(&overwriteFlag, "overwrite", false, "Overwrite existing project metadata")
	importCmd.BoolVar(&strictFlag, "strict", false, "Abort on first task validation error")
	importCmd.BoolVar(&forceDocsFlag, "force-docs", false, "Allow duplicate document attachments")
	importCmd.BoolVar(&quietFlag, "q", false, "Suppress non-essential messages (shorthand)")
	importCmd.BoolVar(&quietFlag, "quiet", false, "Suppress non-essential messages")

	flagArgs, posArgs := splitFlagsAndPosArgs(args, nil)
	if err := importCmd.Parse(flagArgs); err != nil {
		return ImportArgs{}, err
	}

	var raw []byte
	if len(posArgs) > 0 && posArgs[0] != "-" {
		var err error
		raw, err = os.ReadFile(posArgs[0])
		if err != nil {
			return ImportArgs{}, fmt.Errorf("failed to read import file: %w", err)
		}
	} else {
		stat, err := os.Stdin.Stat()
		if err == nil && (stat.Mode()&os.ModeCharDevice) != 0 && len(posArgs) == 0 {
			return ImportArgs{}, fmt.Errorf("input file is required or pipe JSON through stdin.\nUsage: task-cli import <file.json> [flags]")
		}
		raw, err = io.ReadAll(os.Stdin)
		if err != nil {
			return ImportArgs{}, fmt.Errorf("failed to read from stdin: %w", err)
		}
	}

	if len(strings.TrimSpace(string(raw))) == 0 {
		return ImportArgs{}, errors.New("empty import data")
	}

	return ImportArgs{
		RawData:   raw,
		Overwrite: overwriteFlag,
		Strict:    strictFlag,
		ForceDocs: forceDocsFlag,
		DryRun:    dryRunFlag,
		Quiet:     quietFlag,
	}, nil
}

// Execute unmarshals the data and executes the import against the database store.
func (a *ImportAction) Execute(ctx *Context, args ImportArgs) (*ImportResultWrapper, error) {
	var data db.TransferData
	if err := json.Unmarshal(args.RawData, &data); err != nil {
		return nil, fmt.Errorf("invalid JSON format: %w", err)
	}

	res, err := ctx.Store.ImportData(ctx.Context(), &data, db.ImportOptions{
		Overwrite: args.Overwrite,
		Strict:    args.Strict,
		ForceDocs: args.ForceDocs,
		DryRun:    args.DryRun,
	})
	if err != nil {
		return nil, err
	}

	return &ImportResultWrapper{
		Result: res,
		DryRun: args.DryRun,
		Quiet:  args.Quiet,
	}, nil
}

// Format renders import summary and warning messages.
func (a *ImportAction) Format(ctx *Context, w io.Writer, wrap *ImportResultWrapper) error {
	if wrap.Quiet {
		return nil
	}

	res := wrap.Result
	if len(res.Warnings) > 0 {
		for _, warn := range res.Warnings {
			fmt.Fprintf(ctx.ErrWriter(), "Warning: %s\n", warn)
		}
	}

	totalImportedProjs := res.ProjectsImported + res.ProjectsUpdated
	totalIgnored := res.ProjectsSkipped + res.TasksSkipped + res.DocumentsSkipped

	prefix := ""
	if wrap.DryRun {
		prefix = "[dry-run] "
	}

	if res.ProjectsUpdated > 0 {
		fmt.Fprintf(w, "%sImportados: %d projetos (%d novos, %d atualizados), %d tarefas, %d documentos. Ignorados: %d.\n",
			prefix, totalImportedProjs, res.ProjectsImported, res.ProjectsUpdated, res.TasksImported, res.DocumentsImported, totalIgnored)
	} else {
		fmt.Fprintf(w, "%sImportados: %d projetos, %d tarefas, %d documentos. Ignorados: %d.\n",
			prefix, totalImportedProjs, res.TasksImported, res.DocumentsImported, totalIgnored)
	}

	return nil
}

// ImportHandler is the standardized handler instance for ImportAction.
var ImportHandler = NewActionHandler(&ImportAction{})

// Import reads JSON data and merges projects, tasks, and documents into the database.
func Import(ctx *Context, args []string) error {
	return ImportHandler.Run(ctx, args)
}
